function moveName(f, action) {
  if(f.zgLoadout==='spray')return action==='d'?(f.crouch?'zgSprayRefill':'zgSpray'):null;
  if(f.zgLoadout==='fists'&&action==='d')return f.crouch?'zgBareHold':(f.facing>0?f.input?.left&&!f.input?.right:f.input?.right&&!f.input?.left)?'zgBareGuard':'zgBareHook';
  if (action === 'a') return f.y > 0 ? 'airLight' : 'light';
  if (action === 'b') return f.y > 0 ? 'airLight' : f.crouch ? 'launcher' : 'medium';
  if (action === 'c') return f.y > 0 ? 'airHeavy' : f.crouch ? 'sweep' : 'heavy';
  if (action === 'd') {
 if(f.id==='raiden_mgs2'){
  if(f.crouch)return 'weaponSwitch';
  if(f.stance==='gun')return (f.facing>0?f.input?.left&&!f.input?.right:f.input?.right&&!f.input?.left)?'reload':'socom';
  return 'hfThrust';
 }
 const back=f.facing>0?f.input?.left&&!f.input?.right:f.input?.right&&!f.input?.left;
 if(!f.crouch&&back&&ROSTER[f.id].backSpecial)return ROSTER[f.id].backSpecial;
 return f.crouch?ROSTER[f.id].secondary:ROSTER[f.id].special;
 }
  return ['throw','super'].includes(action) ? action : null;
}

getMove.text:
function getMove(f,name) {
 if(name==='acPlay'&&ROSTER[f.id]?.cardDeck){
  const key=f.attack?.name==='acPlay'&&f.attack.cardKey?f.attack.cardKey:f.cards?.hand[f.cards.selected??0];
  const card=ACID_CARDS[key]||ACID_CARDS[ACID_DECKS[f.id][0]];
  return {...MOVES[card.move],acidCard:key||ACID_DECKS[f.id][0],acidCost:card.cost};
 }
 const base={...MOVES[name],...(FIGHTER_MOVES[f.id]?.[name]||{})};
 if(f.zgLoadout==='fists'&&name==='super')return {...MOVES.super,startup:16,active:4,recovery:47,damage:2800,reach:146,level:'throw'};
 if(f.id==='raiden_mgs2'&&f.stance==='gun'&&['light','medium','heavy','airHeavy'].includes(name))return {...MOVES[name],blade:false};
 return base;
}
